<script setup>import {ref,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {publicApi} from '../../api/blog';import ArticleCard from '../../components/ArticleCard.vue';const route=useRoute(),data=ref({records:[],total:0}),categories=ref([]),page=ref(1),categoryId=ref();async function load(){data.value=await publicApi.articles({page:page.value,size:8,categoryId:categoryId.value})}onMounted(async()=>{categories.value=await publicApi.categories();categoryId.value=route.query.categoryId;load()});watch(categoryId,()=>{page.value=1;load()})</script><template><div class="page-head"><h1>全部文章</h1><el-select v-model="categoryId" clearable placeholder="全部分类" style="width:160px"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></div><ArticleCard v-for="a in data.records" :key="a.id" :article="a"/><el-empty v-if="!data.records.length" description="暂无文章"/><el-pagination v-model:current-page="page" :page-size="8" :total="data.total" layout="prev, pager, next" @current-change="load"/></template>
